<?php require __DIR__.'/partials/header.php';$symbol=strtoupper(trim($_GET['symbol']??'AAPL'));$stock=[];$prices=[];try{$stock=q('SELECT * FROM stocks WHERE symbol=?',[$symbol])->fetch()?:[];$prices=q('SELECT ts,close,volume FROM prices WHERE symbol=? ORDER BY ts DESC LIMIT 250',[$symbol])->fetchAll();$prices=array_reverse($prices);}catch(Throwable $x){} ?><section class="section-head"><div><span class="eyebrow">STOCK RESEARCH</span><h1><?=e($symbol)?></h1><p><?=e($stock['name']??'No fundamentals imported yet')?></p></div><a class="secondary" href="watchlist.php?add=<?=urlencode($symbol)?>">Add to watchlist</a></section><div class="grid four"><div class="card"><small>Last price</small><strong><?=e(end($prices)['close']??'—')?></strong></div><div class="card"><small>Market cap</small><strong><?=e($stock['market_cap']??'—')?></strong></div><div class="card"><small>P/E</small><strong><?=e($stock['pe']??'—')?></strong></div><div class="card"><small>Beta</small><strong><?=e($stock['beta']??'—')?></strong></div></div><article class="card chart-card"><div class="card-title"><b>Price history</b><span>Cached observations</span></div><canvas id="priceChart"></canvas></article><div class="grid two"><article class="card"><h3>Fundamentals</h3><dl><dt>Revenue growth</dt><dd><?=e($stock['revenue_growth']??'—')?></dd><dt>EPS growth</dt><dd><?=e($stock['eps_growth']??'—')?></dd><dt>EPS</dt><dd><?=e($stock['eps']??'—')?></dd><dt>Dividend yield</dt><dd><?=e($stock['dividend_yield']??'—')?></dd></dl></article><article class="card"><h3>Research notes</h3><p>Use the historical series and reported fundamentals to investigate a company. Quantix does not provide personalized financial advice.</p></article></div><script>window.QUANTIX_PRICE=<?=json_encode($prices)?>;</script><script src="assets/js/stock.js"></script><?php require __DIR__.'/partials/footer.php'; ?>